import { create } from 'zustand';
import { GamePhase, WeatherType } from '../types';

interface GameState {
  // State
  phase: GamePhase;
  weather: WeatherType;
  dayNumber: number;
  timeOfDay: number; // 0-100 representing day progress
  isPaused: boolean;
  lastUpdateTime: number;

  // Actions
  setPhase: (phase: GamePhase) => void;
  setWeather: (weather: WeatherType) => void;
  advanceDay: () => void;
  updateTimeOfDay: (delta: number) => void;
  togglePause: () => void;
  startGame: () => void;
  endGame: () => void;
  resetGame: () => void;
}

export const useGameStore = create<GameState>((set, _get) => ({
  // Initial state
  phase: 'menu',
  weather: 'sunny',
  dayNumber: 1,
  timeOfDay: 0,
  isPaused: false,
  lastUpdateTime: Date.now(),

  // Actions
  setPhase: (phase) => set({ phase }),

  setWeather: (weather) => set({ weather }),

  advanceDay: () => set((state) => ({
    dayNumber: state.dayNumber + 1,
    timeOfDay: 0,
    // Randomize weather for new day
    weather: getRandomWeather(),
  })),

  updateTimeOfDay: (delta) => set((state) => {
    const newTime = state.timeOfDay + delta;
    if (newTime >= 100) {
      // Day has ended, advance to next day
      return {
        timeOfDay: 0,
        dayNumber: state.dayNumber + 1,
        weather: getRandomWeather(),
      };
    }
    return { timeOfDay: newTime };
  }),

  togglePause: () => set((state) => ({
    isPaused: !state.isPaused,
    phase: state.isPaused ? 'playing' : 'paused',
  })),

  startGame: () => set({
    phase: 'playing',
    isPaused: false,
    lastUpdateTime: Date.now(),
  }),

  endGame: () => set({
    phase: 'gameover',
    isPaused: false,
  }),

  resetGame: () => set({
    phase: 'menu',
    weather: 'sunny',
    dayNumber: 1,
    timeOfDay: 0,
    isPaused: false,
    lastUpdateTime: Date.now(),
  }),
}));

// Helper function to get random weather
function getRandomWeather(): WeatherType {
  const weathers: WeatherType[] = ['sunny', 'sunny', 'sunny', 'rainy', 'foggy'];
  // Sunny is more common (60% chance)
  return weathers[Math.floor(Math.random() * weathers.length)];
}
